#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Reproduce the fixture with pinned, unmodified upstream writer functions.

Development only: this is not used by CVEDelta at runtime. No network access.
"""

import argparse
import ast
import hashlib
import json
from pathlib import Path
import sys
import tempfile
import types

ROOT = Path(__file__).resolve().parent
REVISION = "fc4316861becc9f0d41857b49f6438929ab4c291"
UPSTREAM = {
    "cve-check.bbclass": "31df590fe953b205845e56cec6ab151ea3c079d99acfe0b99002c53baeb4bfc0",
    "cve_check.py": "85b134ad97f4386706d5435fd0c8c7060a440a636a4f5dfeabd67a37b8e4ce5c",
    "LICENSE.MIT": "7557cb18e41b5506cd83c524cc56b6114107ad7c16f5b15348597c8931bfcd53",
}


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def load_upstream(name):
    data = (ROOT / "upstream" / name).read_bytes()
    if sha256(data) != UPSTREAM[name]:
        raise ValueError("pinned upstream checksum mismatch: " + name)
    return data.decode("utf-8")


def definitions(source, names, filename):
    """Compile only named functions, preserving their upstream AST unchanged."""
    tree = ast.parse(source, filename=filename)
    nodes = [node for node in tree.body
             if isinstance(node, ast.FunctionDef) and node.name in names]
    if {node.name for node in nodes} != set(names):
        raise ValueError("missing upstream functions")
    return compile(ast.Module(body=nodes, type_ignores=[]), filename, "exec")


def generate():
    load_upstream("LICENSE.MIT")
    decoder = types.ModuleType("oe.cve_check")
    exec(definitions(load_upstream("cve_check.py"), ["decode_cve_status"],
                     "upstream/cve_check.py"), decoder.__dict__)
    oe = types.ModuleType("oe")
    oe.cve_check = decoder
    sys.modules["oe"] = oe
    sys.modules["oe.cve_check"] = decoder

    source = load_upstream("cve-check.bbclass")
    # The BitBake class is not a Python module. This exact contiguous span is
    # plain Python containing both unmodified JSON producer functions.
    source = source[source.index("def cve_check_write_json_output("):
                    source.index("def cve_write_data(d,")]
    namespace = {"bb": types.SimpleNamespace(note=lambda message: None)}
    exec(definitions(source, ["cve_check_write_json_output", "cve_write_data_json"],
                     "upstream/cve-check.bbclass"), namespace)
    inputs = json.loads((ROOT / "input.json").read_bytes())
    database_bytes = (ROOT / "database.json").read_bytes()

    class Data:
        def getVar(self, name):
            return variables.get(name, "")

        def getVarFlag(self, name, flag):
            return inputs["flags"].get(name, {}).get(flag)

    with tempfile.TemporaryDirectory(prefix="cvedelta-producer-") as temporary:
        output = Path(temporary) / "report.json"
        variables = dict(inputs["recipe"], CVE_CHECK_LOG_JSON=str(output))
        namespace["cve_write_data_json"](
            Data(), inputs["patched"], inputs["unpatched"], inputs["ignored"],
            json.loads(database_bytes), inputs["products"])
        report = output.read_bytes()

    metadata = {
        "schema_version": 1,
        "report_sha256": sha256(report),
        "firmware": {
            "configuration_id": "fixture:local:writer",
            "build_id": "original-writer-fixture-v1",
            "source_revision": sha256((ROOT / "input.json").read_bytes()),
        },
        "scanner": {"name": "yocto-cve-check", "revision": REVISION},
        "database": {"sha256": sha256(database_bytes)},
        "coverage": {
            "scope_sha256": sha256((ROOT / "coverage-policy.json").read_bytes()),
            "complete": True,
        },
    }
    return {"report.json": report,
            "report.meta.json": (json.dumps(metadata, indent=2) + "\n").encode()}


def manifest():
    paths = sorted(path for path in ROOT.rglob("*")
                   if path.is_file() and path.name != "SHA256SUMS"
                   and "__pycache__" not in path.parts)
    return "".join(sha256(path.read_bytes()) + "  " +
                   path.relative_to(ROOT).as_posix() + "\n" for path in paths)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true", help="regenerate checked-in files")
    mode.add_argument("--check", action="store_true", help="check exact generated bytes")
    args = parser.parse_args()
    for name, data in generate().items():
        path = ROOT / name
        if args.write:
            path.write_bytes(data)
        elif not path.exists() or path.read_bytes() != data:
            raise ValueError("generated bytes differ: " + name)
    expected = manifest()
    if args.write:
        (ROOT / "SHA256SUMS").write_text(expected, encoding="utf-8")
    elif (ROOT / "SHA256SUMS").read_text(encoding="utf-8") != expected:
        raise ValueError("fixture manifest mismatch")
    print("producer fixture: exact bytes and checksums verified")


if __name__ == "__main__":
    main()
